#!/usr/bin/env node
// Generates src/terminal/xtermBundle.gen.ts — the vendored renderer payload
// the terminal WebView loads as one inline HTML string.
//
// WHY VENDOR AT ALL. docs/research/terminal.md §3.1: `source={{html}}` is the
// only delivery mechanism that behaves identically in dev and in a TestFlight
// build (`file://` + expo-asset points at the Metro dev server in development),
// and it needs everything — xterm, the fit addon, the stylesheet, the font —
// inlined, because the page's own network requests are not something a
// cookie-gated tailnet host will serve to an `about:blank` document. hub-app
// also cannot depend on @xterm/* directly: the port ships no bundler step of
// its own and the package list is frozen, so the bytes are copied out of the
// PWA's node_modules (the SAME versions the PWA renders with — that is the
// parity claim). The PWA is not part of this repo, so the claim is pinned
// against THIRD-PARTY-NOTICES.md by xtermHtml.test.ts, and this generator skips
// (see scripts/pwa.mjs) when there is no PWA to vendor from.
//
//   node scripts/gen-xterm-bundle.mjs         # write the generated module
//   node scripts/gen-xterm-bundle.mjs --check # exit 1 if it is stale
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import { skipPwa } from './pwa.mjs';

const root = dirname(dirname(fileURLToPath(import.meta.url)));
const pwa = join(root, '..', 'hub');
const outPath = join(root, 'src', 'terminal', 'xtermBundle.gen.ts');
const checkMode = process.argv.includes('--check');

// The vendored bytes are read out of the PWA's node_modules, and the PWA is not
// part of this repo. Without it there is nothing to re-vendor from and nothing
// to prove the committed bundle fresh against — skip rather than die on a path
// that was never here. (`--check` is the mode the `check` script runs.)
if (!existsSync(join(pwa, 'package.json'))) {
  if (checkMode) {
    // Exit with the "not verified" status, never 0 — see scripts/pwa.mjs.
    process.exit(skipPwa('xterm bundle freshness (src/terminal/xtermBundle.gen.ts vs the PWA node_modules)'));
  }
  console.error(`FAIL: the PWA is not checked out beside the app (looked for ${pwa}).`);
  console.error("The vendored bytes are copied from the PWA's node_modules — check the PWA out and run `npm install` in it first.");
  process.exit(1);
}

const XTERM = join(pwa, 'node_modules', '@xterm', 'xterm');
const FIT = join(pwa, 'node_modules', '@xterm', 'addon-fit');
const FONT = join(root, 'assets', 'fonts', 'HubMono-400.ttf');

function read(path) {
  try {
    return readFileSync(path, 'utf8');
  } catch {
    console.error(`FAIL: cannot read ${path}.`);
    console.error('The vendored bytes come from the PWA\'s node_modules — run `npm install` in apps/hub first.');
    process.exit(1);
  }
}

/** A `</script` or `</style` inside the payload would end the tag early and
 * turn the rest of the bundle into markup. Neither file has one today; this
 * fails the build rather than shipping a terminal that renders as text. */
function assertInlineSafe(name, source) {
  if (/<\/(script|style)/i.test(source)) {
    console.error(`FAIL: ${name} contains a </script or </style sequence and cannot be inlined verbatim.`);
    process.exit(1);
  }
}

const version = (dir) => JSON.parse(read(join(dir, 'package.json'))).version;

// The .map files are not vendored, so the reference would be a dead fetch.
const stripSourceMap = (js) => js.replace(/\n?\/\/# sourceMappingURL=.*$/, '');

const xtermJs = stripSourceMap(read(join(XTERM, 'lib', 'xterm.js')));
const fitJs = stripSourceMap(read(join(FIT, 'lib', 'addon-fit.js')));
const xtermCss = read(join(XTERM, 'css', 'xterm.css'));

assertInlineSafe('@xterm/xterm', xtermJs);
assertInlineSafe('@xterm/addon-fit', fitJs);
assertInlineSafe('xterm.css', xtermCss);

// The fit addon's UMD footer is `e.FitAddon=t()`, i.e. the global is the
// module NAMESPACE (`{FitAddon: class}`), while xterm's spreads its exports
// onto globalThis (`globalThis.Terminal` is the class). The shim constructs
// `new FitAddon.FitAddon()` because of that asymmetry; if a future version
// flattens it, the shim silently stops fitting, so pin the footer here.
if (!fitJs.includes('e.FitAddon=t()')) {
  console.error('FAIL: @xterm/addon-fit no longer exports a namespaced UMD global — update the shim in xtermHtml.ts.');
  process.exit(1);
}
if (!xtermJs.includes('e.Terminal=')) {
  console.error('FAIL: @xterm/xterm no longer exports Terminal — update the shim in xtermHtml.ts.');
  process.exit(1);
}

const fontBase64 = readFileSync(FONT).toString('base64');

const output = `// GENERATED by scripts/gen-xterm-bundle.mjs — do not edit.
//
// The four payloads the terminal WebView page is built from: xterm ${version(XTERM)}
// and its fit addon ${version(FIT)} (the PWA's own versions, byte-for-byte out of
// apps/hub/node_modules), the stylesheet they need, and HubMono-400 as base64
// for an inline @font-face. xtermHtml.ts assembles them plus the bridge shim.
//
// Regenerate: node scripts/gen-xterm-bundle.mjs

export const XTERM_VERSION = '${version(XTERM)}';
export const FIT_ADDON_VERSION = '${version(FIT)}';
/** The face the PWA renders with, instanced for RN (src/theme/fonts.ts). */
export const MONO_FONT_FILE = 'HubMono-400.ttf';

// theme-exempt: vendored @xterm/xterm — third-party source, not app styling.
export const XTERM_JS = ${JSON.stringify(xtermJs)};

// theme-exempt: vendored @xterm/addon-fit — third-party source, not app styling.
export const FIT_ADDON_JS = ${JSON.stringify(fitJs)};

// theme-exempt: vendored xterm.css — third-party stylesheet; every colour the
// terminal actually paints comes from the --term-* tokens pushed into
// term.options.theme at runtime.
export const XTERM_CSS = ${JSON.stringify(xtermCss)};

export const MONO_FONT_BASE64 = ${JSON.stringify(fontBase64)};
`;

const sizes = `xterm ${version(XTERM)} ${xtermJs.length}B, fit ${version(FIT)} ${fitJs.length}B, css ${xtermCss.length}B, font ${fontBase64.length}B b64`;

if (checkMode) {
  let current;
  try {
    current = readFileSync(outPath, 'utf8');
  } catch {
    console.error(`FAIL: ${outPath} does not exist. Run "node scripts/gen-xterm-bundle.mjs".`);
    process.exit(1);
  }
  if (current !== output) {
    console.error('FAIL: src/terminal/xtermBundle.gen.ts is stale — run "node scripts/gen-xterm-bundle.mjs" and commit the result.');
    process.exit(1);
  }
  console.log(`ok: xtermBundle.gen.ts matches the vendored sources (${sizes})`);
} else {
  writeFileSync(outPath, output);
  console.log(`wrote ${outPath} (${sizes})`);
}
